[{"agent": "coding_agent", "event": "call", "tool": "save_code", "arguments": {"code": "/*
  Two-Wheel Obstacle Avoiding Robot
  Uses an HC-SR04 Ultrasonic Sensor and L298N Motor Driver
*/

// Ultrasonic Sensor Pins
const int trigPin = 8;
const int echoPin = 7;

// Left Motor Pins (L298N)
const int leftMotorForward = 5;
const int leftMotorBackward = 4;
const int leftMotorSpeed = 3;

// Right Motor Pins (L298N)
const int rightMotorForward = 12;
const int rightMotorBackward = 13;
const int rightMotorSpeed = 11;

// Obstacle distance threshold in cm
const int obstacleDistance = 20;

void setup() {
  // Set motor pins as outputs
  pinMode(leftMotorForward, OUTPUT);
  pinMode(leftMotorBackward, OUTPUT);
  pinMode(leftMotorSpeed, OUTPUT);

  pinMode(rightMotorForward, OUTPUT);
  pinMode(rightMotorBackward, OUTPUT);
  pinMode(rightMotorSpeed, OUTPUT);

  // Set ultrasonic sensor pins
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);

  // Initialize serial for debugging (optional)
  Serial.begin(9600);
}

void loop() {
  long duration, distance;

  // Send a 10us pulse to trigger the sensor
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Read the echo pin to get the duration
  duration = pulseIn(echoPin, HIGH);

  // Calculate distance in cm
  distance = (duration / 2) / 29.1;

  // Debug output
  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  // Check for obstacles
  if (distance > obstacleDistance) {
    moveForward();
  } else {
    // Obstacle detected
    stopRobot();
    delay(300);

    moveBackward();
    delay(500);

    stopRobot();
    delay(200);

    turnRight();
    delay(600);

    stopRobot();
    delay(200);
  }
}

void moveForward() {
  digitalWrite(leftMotorForward, HIGH);
  digitalWrite(leftMotorBackward, LOW);
  analogWrite(leftMotorSpeed, 200); // Speed 0-255

  digitalWrite(rightMotorForward, HIGH);
  digitalWrite(rightMotorBackward, LOW);
  analogWrite(rightMotorSpeed, 200);
}

void moveBackward() {
  digitalWrite(leftMotorForward, LOW);
  digitalWrite(leftMotorBackward, HIGH);
  analogWrite(leftMotorSpeed, 150);

  digitalWrite(rightMotorForward, LOW);
  digitalWrite(rightMotorBackward, HIGH);
  analogWrite(rightMotorSpeed, 150);
}

void turnRight() {
  digitalWrite(leftMotorForward, HIGH);
  digitalWrite(leftMotorBackward, LOW);
  analogWrite(leftMotorSpeed, 180);

  digitalWrite(rightMotorForward, LOW);
  digitalWrite(rightMotorBackward, HIGH);
  analogWrite(rightMotorSpeed, 180);
}

void stopRobot() {
  digitalWrite(leftMotorForward, LOW);
  digitalWrite(leftMotorBackward, LOW);
  analogWrite(leftMotorSpeed, 0);

  digitalWrite(rightMotorForward, LOW);
  digitalWrite(rightMotorBackward, LOW);
  analogWrite(rightMotorSpeed, 0);
}", "filename": "obstacle_avoiding_robot.ino"}, "tool_call_id": "xwfs1qbxb"}, {"agent": "coding_agent", "event": "result", "tool": "save_code", "content": "{"saved": true, "path": "/Users/rayentabet/Desktop/InMind/Assignment_10/generated/code/obstacle_avoiding_robot.ino"}", "tool_call_id": "xwfs1qbxb"}, {"agent": "coding_agent", "event": "call", "tool": "validate_code", "arguments": {"filename": "obstacle_avoiding_robot.ino"}, "tool_call_id": "eh61tk5j8"}, {"agent": "coding_agent", "event": "result", "tool": "validate_code", "content": "{"valid": true, "errors": []}", "tool_call_id": "eh61tk5j8"}, {"agent": "robot_visualization_agent", "event": "call", "tool": "save_openscad", "arguments": {"model_name": "robot_model", "code": "// Robot Chassis
module chassis() {
    color("gray")
    cube([100, 80, 10], center=true);
}

// Wheels
module wheel() {
    color("black")
    rotate([90, 0, 0])
    cylinder(r=20, h=10, center=true);
}

// HC-SR04 Sensor
module sensor() {
    color("blue")
    cube([40, 10, 20], center=true);
}

// Assembly
union() {
    // Chassis
    chassis();

    // Wheels
    translate([-40, 45, 0]) wheel();
    translate([40, 45, 0]) wheel();
    translate([-40, -45, 0]) wheel();
    translate([40, -45, 0]) wheel();

    // Sensor
    translate([0, 45, 15]) sensor();

    // Battery/Controller placeholder
    translate([0, 0, 10]) color("red") cube([50, 50, 20], center=true);
}
